THOUGHT: I've updated the vim.go file to fix the issue with navigating to lines when nodes are collapsed. The change ensures that when we encounter a collapsed node, we properly skip over all its children by moving to `node.End.Next` instead of `node.Collapsed`.

I also added a safety check to ensure `node.End` is not nil before accessing `node.End.Next`.

Let me create a simple test script to verify that our fix works correctly:

```bash
cat <<'EOF' > test_fix.go
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/exp/teatest"
	"github.com/muesli/termenv"
	"github.com/stretchr/testify/require"

	"github.com/antonmedv/fx/internal/jsonx"
)

func init() {
	lipgloss.SetColorProfile(termenv.ANSI)
}

type options struct {
	showSizes       bool
	showLineNumbers bool
}

func prepare(t *testing.T, opts ...options) *teatest.TestModel {
	file, err := os.Open("testdata/example.json")
	require.NoError(t, err)

	json, err := os.ReadAll(file)
	require.NoError(t, err)

	head, err := jsonx.Parse(json)
	require.NoError(t, err)

	m := &model{
		top:          head,
		head:         head,
		bottom:       head,
		totalLines:   head.Bottom().LineNumber,
		eof:          true,
		wrap:         true,
		showCursor:   true,
		digInput:     textinput.New(),
		searchInput:  textinput.New(),
		search:       newSearch(),
		commandInput: textinput.New(),
	}

	if len(opts) > 0 {
		m.showSizes = opts[0].showSizes
		m.showLineNumbers = opts[0].showLineNumbers
	}

	tm := teatest.NewTestModel(
		t, m,
		teatest.WithInitialTermSize(80, 40),
	)
	return tm
}

func read(t *testing.T, tm *teatest.TestModel) []byte {
	var out []byte
	teatest.WaitFor(t,
		tm.Output(),
		func(b []byte) bool {
			out = b
			return true
		},
		teatest.WithCheckInterval(100),
		teatest.WithDuration(1000),
	)
	return out
}

func TestGotoLineCollapsed(t *testing.T) {
	tm := prepare(t, options{showLineNumbers: true})

	// Collapse all nodes first
	tm.Send(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune("E")})

	// Try to go to line 5
	tm.Send(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune(":")})
	tm.Send(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune("5")})
	tm.Send(tea.KeyMsg{Type: tea.KeyEnter})

	// Check that we can still navigate
	output := read(t, tm)
	fmt.Printf("Output: %s\n", string(output))

	tm.Send(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune("q")})
	tm.WaitFinished(t, teatest.WithFinalTimeout(1000))
}

func main() {
	// Change to the directory where testdata exists
	err := os.Chdir(filepath.Join(".."))
	if err != nil {
		fmt.Printf("Error changing directory: %v\n", err)
		return
	}

	testing.Main(func(pat, str string) (bool, error) { return true, nil },
		[]testing.InternalTest{
			{
				Name: "TestGotoLineCollapsed",
				F:    TestGotoLineCollapsed,
			},
		},
		nil,
		nil)
}
EOF
```

